import {readFileSync} from 'node:fs';
import {randomUUID} from 'node:crypto';
import {PGlite} from '@electric-sql/pglite';
import {beforeAll,afterAll,beforeEach,it,expect} from 'vitest';
import {z} from 'zod';
import {revisionSchema,bindingSchema,eventSchema,statusSchema} from '../lib/payments/cluera/contracts';

// Entirely synthetic, in-memory PostgreSQL. No hosted database or provider call.
const user=randomUUID(),session=randomUUID(),actor=randomUUID(),adminSession=randomUUID();
const digest='a'.repeat(64),eventDigest='b'.repeat(64),pack='cluera_pack_3h_v2',monthly='cluera_monthly_40h_v2';
const baseline=['20261004024730_customer_account_foundation','20261004025407_paddle_sandbox_inbox','20261004064105_shared_usage_reservations',
 '20261004070733_sandbox_checkout_intents','20261004072754_sandbox_pack_allowances','20261004081006_sandbox_billing_jobs','20261004081025_sandbox_recurring_lifecycle',
 '20261004081416_sandbox_refund_schedule_boundaries','20261004141346_account_workspace_controls','20261008100006_account_admin_catalog_controls',
 '20261009120157_account_credits_snapshot','20261011014422_account_checkout_unresolved_bound_guard'];
let db:PGlite;let preservedBefore:unknown,preservedAfter:unknown;let fixturePaidAt:string;
const tables=['customer_accounts','customer_trial_grants','customer_checkout_intents','customer_usage_grants','account_catalog_policy'];
async function call(name:string,args:unknown[]=[]){return(await db.query<{value:any}>(`select public.${name}(${args.map((_,i)=>'$'+(i+1)).join(',')}) value`,args)).rows[0].value;}
async function rows(table:string){return(await db.query<any>(`select * from ${table}`)).rows;}
async function snapshot(){const value:Record<string,unknown>={};for(const t of tables)value[t]=await rows('public.'+t);value.oldIntent=await rows('billing_private.payment_intents');return value;}
async function billingSnapshot(){const value:Record<string,unknown>={};for(const t of ['subscriptions','payments','terms','intents'])value[t]=await rows('cluera_billing_private.'+t);value.grants=await rows('public.customer_usage_grants');return value;}
async function makeUsers(){for(const [u,s] of[[user,session],[actor,adminSession]]){await db.query('insert into auth.users values($1,$2,now())',[u,u+'@example.invalid']);await db.query("insert into auth.sessions values($1,$2,null,'aal2')",[s,u]);await call('customer_authorize',[u,s]);}await db.query('insert into public.account_admin_profiles(user_id) values($1)',[actor]);}
beforeAll(async()=>{
 db=new PGlite();await db.exec('create role anon;create role authenticated;create role service_role bypassrls;create schema auth;create table auth.users(id uuid primary key,email text,email_confirmed_at timestamptz);create table auth.sessions(id uuid primary key,user_id uuid,not_after timestamptz,aal text);');
 for(const m of baseline)await db.exec(readFileSync(`../supabase/migrations/${m}.sql`,'utf8'));
 await db.exec('create schema if not exists billing_private;create table billing_private.worker_config(singleton boolean primary key,secret_id uuid,enabled boolean,last_sent_at timestamptz,last_request_id bigint);');
 await db.exec(readFileSync('../supabase/migrations/20261004093908_checkout_recovery_audit.sql','utf8'));
 await db.exec(readFileSync('../supabase/migrations/20261012013828_account_gateway_test_pack.sql','utf8'));
 await makeUsers();const old=await call('account_payment_prepare',[user,session,randomUUID(),digest]);await call('account_payment_bind',[old.intentId,old.attemptId,digest,'order_originalbound01']);
 preservedBefore=await snapshot();await db.exec(readFileSync('../docs/proposals/cluera-billing.sql','utf8'));preservedAfter=await snapshot();
},60000);
beforeEach(async()=>{
 fixturePaidAt=new Date(Math.floor(Date.now()/1000)*1000).toISOString();
 const immutable=['catalog_revisions','plan_verifications','admin_audit','cutover_audit','worker_nonces','applications'];
 for(const t of immutable)await db.exec(`alter table cluera_billing_private.${t} disable trigger immutable`);
 await db.exec('alter table billing_private.payment_applications disable trigger payment_applications_immutable;alter table billing_private.payment_diagnostics disable trigger payment_diagnostics_immutable;alter table billing_private.checkout_recovery_audit disable trigger checkout_recovery_audit_immutable;truncate public.customer_accounts,auth.users,auth.sessions,public.paddle_sandbox_events,billing_private.payment_events cascade;');
 await db.exec('truncate cluera_billing_private.catalog_revisions,cluera_billing_private.events,cluera_billing_private.plan_verifications,cluera_billing_private.admin_audit,cluera_billing_private.cutover_audit,cluera_billing_private.worker_nonces cascade;update cluera_billing_private.processing_owner set owner=\'account\',epoch=1,account_digest=null;');
 await db.exec("insert into cluera_billing_private.catalog_revisions(offer_code,version,name,amount_paise,allowance_seconds,kind,interval_name,total_count) values('cluera_pack_3h_v2',1,'Cluera 3 Hours',54900,10800,'PACK',null,null),('cluera_monthly_40h_v2',1,'Cluera Pro 40 Hours Monthly',549900,144000,'RECURRING','MONTH',120),('cluera_monthly_100h_v2',1,'Cluera Pro 100 Hours Monthly',959900,360000,'RECURRING','MONTH',120),('cluera_monthly_200h_v2',1,'Cluera Enterprise 200 Hours Monthly',1954900,720000,'RECURRING','MONTH',120);insert into cluera_billing_private.catalog_heads(offer_code,revision_id) select offer_code,id from cluera_billing_private.catalog_revisions;");
 for(const t of immutable)await db.exec(`alter table cluera_billing_private.${t} enable always trigger immutable`);
 await db.exec('alter table billing_private.payment_applications enable always trigger payment_applications_immutable;alter table billing_private.payment_diagnostics enable always trigger payment_diagnostics_immutable;alter table billing_private.checkout_recovery_audit enable always trigger checkout_recovery_audit_immutable;');
 await makeUsers();
});
afterAll(async()=>db?.close());
async function catalog(offer=pack){return(await call('cluera_billing_catalog')).find((r:any)=>r.offerCode===offer);}
async function admin(action:string,input:unknown,offer=pack,op=randomUUID(),expected?:string){return call('cluera_billing_admin_mutate',[actor,adminSession,op,action,offer,expected??(await catalog(offer)).revisionId,new Date().toISOString(),'Synthetic owner approved catalog change',input]);}
async function cutover(owner='cluera',expectedOwner='account',epoch=1,op=randomUUID()){return call('cluera_billing_cutover',[op,expectedOwner,epoch,owner,digest,'Synthetic explicitly approved ownership transfer']);}
async function enable(offer=pack){if(offer!==pack){const r=await catalog(offer);const result=await admin('CREATE_REVISION',{name:r.name,amountPaise:r.amountPaise,allowanceSeconds:r.allowanceSeconds,razorpayPlanId:'plan_synthetic0001',totalCount:120},offer);expect(result.code).toBe('APPLIED');const x=await catalog(offer);expect(await call('cluera_billing_plan_verify',[x.revisionId,digest,{planId:x.razorpayPlanId,period:'monthly',interval:1,amountPaise:x.amountPaise,currency:'INR',observedAt:new Date().toISOString()}])).toBe('VERIFIED');}expect((await admin('SET_ENABLED',{enabled:true},offer)).code).toBe('APPLIED');}
async function bound(offer=pack){const r=await catalog(offer);const i=await call('cluera_billing_prepare',[user,session,randomUUID(),r.revisionId,digest,2]);expect(i.code).toBe('CLAIMED');expect(await call('cluera_billing_bind',[i.intentId,i.attemptId,digest,2,offer===pack?{orderId:'order_synthetic0001'}:{subscriptionId:'sub_synthetic0001'}])).toBe('BOUND');return i;}
function event(n=1,type='payment.captured',recurring=false){return{eventId:'evt_synthetic000'+n,eventType:type,resourceId:type==='refund.processed'?'rfnd_synthetic0001':type.startsWith('subscription.')?'sub_synthetic0001':type==='order.paid'?'order_synthetic0001':'pay_synthetic0001',paymentId:type==='subscription.authenticated'?null:'pay_synthetic0001',orderId:type==='subscription.authenticated'?null:'order_synthetic0001',subscriptionId:recurring?'sub_synthetic0001':null,invoiceId:recurring&&type!=='subscription.authenticated'?'inv_synthetic0001':null,digest:eventDigest,occurredAt:new Date().toISOString()};}
function evidence(i:any,action='GRANT',recurring=false){const ps=new Date();ps.setUTCDate(1);ps.setUTCHours(0,0,0,0);const pe=new Date(ps);pe.setUTCMonth(pe.getUTCMonth()+1);return{action,intentId:i.intentId,orderId:action==='STATUS'?null:'order_synthetic0001',paymentId:action==='STATUS'?null:'pay_synthetic0001',invoiceId:recurring&&action!=='STATUS'?'inv_synthetic0001':null,subscriptionId:recurring?'sub_synthetic0001':null,amountPaise:recurring?549900:54900,currency:'INR',observedAt:new Date().toISOString(),periodStart:recurring&&action!=='STATUS'?ps.toISOString():null,periodEnd:recurring&&action!=='STATUS'?pe.toISOString():null,subscriptionState:recurring?'ACTIVE':null,paidAt:recurring&&action!=='STATUS'?fixturePaidAt:null,cancellationAt:null,refundId:action==='REFUND'?'rfnd_synthetic0001':null};}
async function apply(i:any,n=1,action='GRANT',recurring=false,overrides:Record<string,unknown>={}){const c=await call('cluera_billing_event_claim',[digest,2]);expect(c.code).toBe('CLAIMED');expect(c.legacy).toBe(false);return call('cluera_billing_apply',['evt_synthetic000'+n,c.claimId,eventDigest,digest,2,{...evidence(i,action,recurring),...overrides}]);}

it('proposal preserves full existing customer/trial/old catalog/ledger/pending-order rows exactly',()=>{expect(preservedAfter).toEqual(preservedBefore);});
it('seeds only four disabled versioned offers, never aliases the old weekly30h policy',async()=>{const c=await call('cluera_billing_catalog');expect(c).toHaveLength(4);expect(c.map((x:any)=>[x.amountPaise,x.allowanceSeconds,x.interval,x.enabled])).toEqual([[54900,10800,null,false],[549900,144000,'MONTH',false],[959900,360000,'MONTH',false],[1954900,720000,'MONTH',false]]);expect((await rows('public.account_catalog_policy')).map(x=>x.offer_code)).toContain('enterprise_weekly');});
it('canonical new checkout cannot run before separate owner CAS, even if catalog is enabled',async()=>{await enable();expect((await call('cluera_billing_prepare',[user,session,randomUUID(),(await catalog()).revisionId,digest,1])).code).toBe('UNAVAILABLE');expect((await call('cluera_billing_owner',[digest])).owner).toBe('account');});
it('Admin MFA, fresh reauthentication, reason and strict replay/CAS protect immutable future changes',async()=>{const r=await catalog();const op=randomUUID();const input={name:'Future price only',amountPaise:59900,allowanceSeconds:14400,razorpayPlanId:null,totalCount:null};expect((await admin('CREATE_REVISION',input,pack,op,r.revisionId)).code).toBe('APPLIED');expect((await admin('CREATE_REVISION',input,pack,op,r.revisionId)).code).toBe('APPLIED');expect((await admin('CREATE_REVISION',{...input,amountPaise:60000},pack,op,r.revisionId)).code).toBe('CONFLICT');expect((await catalog()).enabled).toBe(false);expect((await rows('cluera_billing_private.catalog_revisions')).find(x=>x.id===r.revisionId).amount_paise).toBe(54900);await db.query("update auth.sessions set aal='aal1' where id=$1",[adminSession]);expect((await admin('SET_ENABLED',{enabled:true})).code).toBe('FORBIDDEN');await expect(db.exec('delete from cluera_billing_private.admin_audit')).rejects.toThrow(/immutable/);});
it('concurrent operation UUIDs claim only one intent; unknown creation never retries a provider claim',async()=>{await cutover();await enable();const r=await catalog();const request=randomUUID();const outcomes=await Promise.all([call('cluera_billing_prepare',[user,session,request,r.revisionId,digest,2]),call('cluera_billing_prepare',[user,session,randomUUID(),r.revisionId,digest,2])]);expect(outcomes.map(x=>x.code).sort()).toEqual(['CLAIMED','PENDING']);const i=outcomes.find(x=>x.code==='CLAIMED');expect(await call('cluera_billing_bind',[i.intentId,i.attemptId,digest,2,null])).toBe('UNCERTAIN');expect((await call('cluera_billing_prepare',[user,session,request,r.revisionId,digest,2])).code).toBe('UNCERTAIN');});
it('two genuine event types require leased server evidence and grant one10800s nonexpiring pack only',async()=>{await cutover();await enable();const i=await bound();await call('cluera_billing_event_accept',[event(),digest]);expect((await apply(i)).code).toBe('VERIFIED');await call('cluera_billing_event_accept',[event(2,'order.paid'),digest]);expect((await apply(i,2)).code).toBe('VERIFIED');const g=await rows('public.customer_usage_grants');expect(g.filter(x=>x.kind==='PACK')).toHaveLength(1);expect(g.find(x=>x.kind==='PACK')).toMatchObject({granted_ms:10800000,expires_at:null});expect(await rows('cluera_billing_private.applications')).toHaveLength(2);expect((await call('cluera_credits_read',[user,session])).availableMilliseconds).toBe(11700000);expect((await call('customer_credits_read',[user,session])).payments).toEqual([]);});
it.each([{amountPaise:54899},{currency:'USD'},{observedAt:null},{observedAt:'2000-01-01T00:00:00Z'},{paymentId:'pay_foreign0001'},{orderId:'order_foreign0001'},{action:'BROWSER_SUCCESS'},{refundId:'rfnd_synthetic0001'}])('rejects callback/fake/stale/mismatched projection without any grant %j',async invalid=>{await cutover();await enable();const i=await bound();await call('cluera_billing_event_accept',[event(),digest]);expect((await apply(i,1,'GRANT',false,invalid)).code).not.toBe('VERIFIED');expect(await rows('public.customer_usage_grants')).toHaveLength(0);});
it('refund before capture permanently tombstones the exact payment/order',async()=>{await cutover();await enable();const i=await bound();await call('cluera_billing_event_accept',[event(1,'refund.processed'),digest]);expect((await apply(i,1,'REFUND')).code).toBe('REFUNDED');await call('cluera_billing_event_accept',[event(2),digest]);expect((await apply(i,2)).code).toBe('REFUNDED');expect(await rows('public.customer_usage_grants')).toHaveLength(0);});
it('full refund settles reservations then revokes only attributable unused grant; trial/history stay intact',async()=>{await cutover();await enable();const i=await bound();await call('cluera_billing_event_accept',[event(),digest]);await apply(i);await db.exec("update public.customer_usage_grants set spent_ms=60000 where kind='PACK'");const trial=await rows('public.customer_trial_grants');await call('cluera_billing_event_accept',[event(2,'refund.processed'),digest]);await apply(i,2,'REFUND');expect((await rows('public.customer_usage_grants'))[0]).toMatchObject({granted_ms:10800000,spent_ms:60000,state:'REVOKED',reserved_ms:0});expect((await rows('cluera_billing_private.applications'))[1].removed_ms).toBe(10740000);expect(await rows('public.customer_trial_grants')).toEqual(trial);});
it('monthly grants only exact independently verified paid invoice cycle and frozen revision amount/time',async()=>{await cutover();await enable(monthly);const i=await bound(monthly);await call('cluera_billing_event_accept',[event(1,'subscription.charged',true),digest]);expect((await apply(i,1,'GRANT',true)).code).toBe('VERIFIED');expect((await rows('public.customer_usage_grants'))[0]).toMatchObject({kind:'RECURRING',granted_ms:144000000});expect((await call('cluera_credits_read',[user,session])).plans[0].tier).toBe('PRO');await admin('CREATE_REVISION',{name:'Changed future plan',amountPaise:650000,allowanceSeconds:180000,razorpayPlanId:'plan_future0001',totalCount:12},monthly);await call('cluera_billing_event_accept',[event(2,'payment.captured',true),digest]);expect((await apply(i,2,'GRANT',true)).code).toBe('VERIFIED');expect(await rows('public.customer_usage_grants')).toHaveLength(1);});
it('mandate/authentication event is audited but creates no allowance or paid subscription',async()=>{await cutover();await enable(monthly);const i=await bound(monthly);await call('cluera_billing_event_accept',[event(1,'subscription.authenticated',true),digest]);expect((await apply(i,1,'STATUS',true)).code).toBe('NO_GRANT');expect(await rows('cluera_billing_private.subscriptions')).toHaveLength(0);expect(await rows('public.customer_usage_grants')).toHaveLength(0);});
it('ownership transfer drains live old leases, fences stale epochs, retains late old signed intake and canonical grant',async()=>{const old=await call('account_payment_prepare',[user,session,randomUUID(),digest]);await call('account_payment_bind',[old.intentId,old.attemptId,digest,'order_synthetic0001']);const x=event();delete (x as any).subscriptionId;delete (x as any).invoiceId;expect(await call('account_payment_receive',[x,digest])).toBe('STORED');const oldClaim=await call('account_payment_claim',[digest]);expect((await cutover()).code).toBe('DRAIN_REQUIRED');await call('account_payment_retry',[x.eventId,oldClaim.claimId]);expect((await cutover()).code).toBe('APPLIED');expect((await call('account_payment_claim',[digest])).code).toBe('EMPTY');expect((await call('cluera_billing_event_claim',[digest,1])).code).toBe('UNAVAILABLE');await db.exec('update billing_private.payment_events set retry_at=now()');const c=await call('cluera_billing_event_claim',[digest,2]);expect(c.legacy).toBe(true);const proof={action:'GRANT',intentId:old.intentId,orderId:x.orderId,paymentId:x.paymentId,amount:54900,currency:'INR',observedAt:new Date().toISOString(),refundId:null};expect((await call('account_payment_apply',[x.eventId,c.claimId,eventDigest,digest,proof])).code).toBe('UNAVAILABLE');expect((await call('cluera_billing_legacy_apply',[x.eventId,c.claimId,eventDigest,digest,2,proof])).code).toBe('VERIFIED');expect(await call('account_payment_receive',[x,digest])).toBe('DUPLICATE');expect(await rows('cluera_billing_private.payments')).toHaveLength(0);expect(await rows('billing_private.payment_applications')).toHaveLength(1);expect((await rows('public.customer_usage_grants'))[0].source_key).toBe('razorpay-test:order_synthetic0001');});
it('short-lived consumed worker nonce rejects replay, old epoch, missing proof and stale issuance',async()=>{await cutover();const n=randomUUID(),at=new Date().toISOString();expect(await call('cluera_billing_worker_nonce',[n,at,2,digest])).toBe('CLAIMED');expect(await call('cluera_billing_worker_nonce',[n,at,2,digest])).toBe('REPLAY');expect(await call('cluera_billing_worker_nonce',[randomUUID(),at,1,digest])).toBe('UNAVAILABLE');expect(await call('cluera_billing_worker_nonce',[null,at,2,digest])).toBe('INVALID');expect(await call('cluera_billing_worker_nonce',[randomUUID(),'2000-01-01T00:00:00Z',2,digest])).toBe('INVALID');});
it('audit failure atomically rolls back financial writer; direct CRUD/public execute remain denied',async()=>{await cutover();await enable();const i=await bound();await call('cluera_billing_event_accept',[event(),digest]);await db.exec("create function cluera_billing_private.fail_audit() returns trigger language plpgsql as $$begin raise exception 'Synthetic audit failure';end$$;create trigger fail_audit before insert on cluera_billing_private.applications for each row execute function cluera_billing_private.fail_audit();");await expect(apply(i)).rejects.toThrow();expect(await rows('public.customer_usage_grants')).toHaveLength(0);expect((await rows('cluera_billing_private.intents'))[0].state).toBe('BOUND');await db.exec('drop trigger fail_audit on cluera_billing_private.applications;drop function cluera_billing_private.fail_audit();');const privateTables=(await db.query<{table_name:string}>("select table_name from information_schema.tables where table_schema='cluera_billing_private'")).rows;for(const t of privateTables)for(const role of['anon','authenticated','service_role'])expect((await db.query<{ok:boolean}>(`select has_table_privilege($1,$2,'SELECT,INSERT,UPDATE,DELETE') ok`,[role,'cluera_billing_private.'+t.table_name])).rows[0].ok).toBe(false);for(const role of['anon','authenticated'])expect((await db.query<{ok:boolean}>(`select has_function_privilege($1,'public.cluera_billing_apply(text,uuid,text,text,bigint,jsonb)','EXECUTE') ok`,[role])).rows[0].ok).toBe(false);expect((await db.query<{proconfig:string[]}>("select proconfig from pg_proc where oid='public.cluera_billing_apply(text,uuid,text,text,bigint,jsonb)'::regprocedure")).rows[0].proconfig).toContain('search_path=""');});
it.each([null,'c'.repeat(64)])('missing/foreign merchant and null sessions never create paid intent %s',async foreign=>{await cutover();await enable();expect((await call('cluera_billing_prepare',[user,session,randomUUID(),(await catalog()).revisionId,foreign,2])).code).toBe('UNAVAILABLE');expect((await call('cluera_billing_status',[user,null])).code).toBe('UNAUTHENTICATED');expect(await rows('cluera_billing_private.intents')).toHaveLength(0);});
it('expired lease, null claim and conflicting signed duplicate cannot become authority',async()=>{await cutover();await enable();const i=await bound();const x=event();await call('cluera_billing_event_accept',[x,digest]);const c=await call('cluera_billing_event_claim',[digest,2]);await db.exec("update cluera_billing_private.events set lease_until=now()-interval '1 second'");expect((await call('cluera_billing_apply',[x.eventId,c.claimId,eventDigest,digest,2,evidence(i)])).code).toBe('CONFLICT');expect((await call('cluera_billing_apply',[x.eventId,null,eventDigest,digest,2,evidence(i)])).code).toBe('INVALID');expect(await call('cluera_billing_event_accept',[{...x,digest:'c'.repeat(64)},digest])).toBe('CONFLICT');expect((await call('cluera_billing_event_claim',[digest,2])).code).toBe('EMPTY');expect(await rows('public.customer_usage_grants')).toHaveLength(0);});
it('a fully funded reservation is settled before full refund and immutable audit pins grant before/after',async()=>{await cutover();await enable();const i=await bound();await call('cluera_billing_event_accept',[event(),digest]);await apply(i);const run=randomUUID();expect((await call('customer_usage_command',[user,session,run,0,'START'])).code).toBe('ACTIVE');expect((await rows('public.customer_usage_grants')).find(x=>x.kind==='PACK').reserved_ms).toBeGreaterThan(0);await call('cluera_billing_event_accept',[event(2,'refund.processed'),digest]);await apply(i,2,'REFUND');const g=(await rows('public.customer_usage_grants')).find(x=>x.kind==='PACK');expect(g.reserved_ms).toBe(0);expect(g.state).toBe('REVOKED');expect((await rows('public.customer_usage_runs'))[0].state).toBe('DENIED');const audit=(await rows('cluera_billing_private.applications'))[1];expect(audit.before_row.grant.reserved_ms).toBeGreaterThan(0);expect(audit.after_row.grant).toMatchObject({state:'REVOKED',reserved_ms:0});expect(await rows('public.customer_usage_settlements')).toHaveLength(1);});
