function invoiceCycle(offsetDays: number) {
 const start = new Date(Date.now() + offsetDays * day), end = new Date(start.getTime() + 30 * day);
 return { periodStart: start.toISOString(), periodEnd: end.toISOString() };
}
function nextInvoice(n: number, type = 'subscription.charged') {
 const paymentId = `pay_synthetic000${n}`, orderId = `order_synthetic000${n}`, invoiceId = `inv_synthetic000${n}`;
 return { ...event(n,type,true),paymentId,orderId,invoiceId,
  resourceId:type==='order.paid'?orderId:type==='refund.processed'?'rfnd_synthetic0001':type.startsWith('subscription.')?'sub_synthetic0001':paymentId };
}
async function receiveInvoice(i: any, n: number, cycle: {periodStart:string;periodEnd:string}, overrides: Record<string,unknown> = {}, type = 'subscription.charged') {
 const x = nextInvoice(n,type); await call('cluera_billing_event_accept',[x,digest]);
 return apply(i,n,type==='refund.processed'?'REFUND':'GRANT',true,{paymentId:x.paymentId,orderId:x.orderId,invoiceId:x.invoiceId,...cycle,...overrides});
}
async function currentAndQueued() {
 await cutover(); await enable(monthly); const i = await bound(monthly), current = invoiceCycle(-10);
 expect((await receiveInvoice(i,1,current)).code).toBe('VERIFIED');
 const queued = { periodStart:current.periodEnd,periodEnd:new Date(new Date(current.periodEnd).getTime()+30*day).toISOString() };
 expect((await receiveInvoice(i,2,queued)).code).toBe('VERIFIED');
 return {i,current,queued};
}
async function advanceRefresh(at: string) {
 // Only the private in-memory test engine receives an injected clock. Hosted
 // public RPCs always supply clock_timestamp(), not caller-controlled time.
 await db.query('select cluera_billing_private.refresh($1,$2)',[user,at]);
}
async function cancelPaidSubscription(i: any, n: number, at = fixturePaidAt) {
 const x = { ...event(n,'subscription.cancelled',true),paymentId:null,orderId:null,invoiceId:null };
 await call('cluera_billing_event_accept',[x,digest]);
 expect((await apply(i,n,'STATUS',true,{subscriptionState:'CANCELED',cancellationAt:at})).code).toBe('APPLIED');
}

