it.each(['ACTIVE','PAST_DUE','PAUSED'])('ended historical Paddle terms do not permit forward cutover while a %s subscription can renew',async state=>{
 const ctm='ctm_'+'c'.repeat(26),sub='sub_'+'c'.repeat(26),txn='txn_'+'c'.repeat(26);
 await db.query('insert into public.customer_paddle_bindings(customer_id,user_id) values($1,$2)',[ctm,user]);
 await db.query("insert into public.customer_recurring_subscriptions(subscription_id,user_id,customer_id,offer_code,tier,state,observed_at,paid_through,cancel_future) values($1,$2,$3,'pro_40_hours','PRO',$4,now(),now()-interval '5 days',false)",[sub,user,ctm,state]);
 await db.query("insert into public.customer_recurring_terms(transaction_id,user_id,subscription_id,state,period_start,period_end) values($1,$2,$3,'ENDED',now()-interval '35 days',now()-interval '5 days')",[txn,user,sub]);
 const beforeSubscriptions=await rows('public.customer_recurring_subscriptions'),beforeTerms=await rows('public.customer_recurring_terms');
 await unchangedCutoverFailure('PADDLE_DRAIN_REQUIRED','cluera','account',1);
 expect(await rows('public.customer_recurring_subscriptions')).toEqual(beforeSubscriptions);expect(await rows('public.customer_recurring_terms')).toEqual(beforeTerms);
 // A separate synthetic authoritative canceled snapshot is drained, with the
 // immutable financial history preserved; this is not a provider cancel call.
 await db.query("update public.customer_recurring_subscriptions set state='CANCELED',cancel_future=true where subscription_id=$1",[sub]);
 expect((await cutover()).code).toBe('APPLIED');
 expect(await rows('public.customer_recurring_terms')).toEqual(beforeTerms);
});
