it.each(['ACTIVE','REFUNDED'])('same-owned resolved Paddle pack %s attribution permits forward cutover without altering historical rows',async state=>{
 const intent=randomUUID(),txn='txn_'+'e'.repeat(26),ctm='ctm_'+'e'.repeat(26),grant=randomUUID();
 await db.query("insert into public.customer_checkout_intents(id,user_id,request_id,offer_code,state,transaction_id) values($1,$2,$3,'pro_3_hours','BOUND',$4)",[intent,user,randomUUID(),txn]);
 await db.query('insert into public.customer_paddle_bindings(customer_id,user_id) values($1,$2)',[ctm,user]);
 if(state==='ACTIVE')await db.query("insert into public.customer_usage_grants(id,user_id,source_key,kind,granted_ms) values($1,$2,'synthetic-resolved-paddle-pack','PACK',10800000)",[grant,user]);
 await db.query('insert into public.customer_pack_purchases(transaction_id,intent_id,user_id,customer_id,state,grant_id) values($1,$2,$3,$4,$5,$6)',[txn,intent,user,ctm,state,state==='ACTIVE'?grant:null]);
 const before={intents:await rows('public.customer_checkout_intents'),packs:await rows('public.customer_pack_purchases'),grants:await rows('public.customer_usage_grants')};
 expect((await cutover()).code).toBe('APPLIED');
 expect({intents:await rows('public.customer_checkout_intents'),packs:await rows('public.customer_pack_purchases'),grants:await rows('public.customer_usage_grants')}).toEqual(before);
});
